using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RewardEventAction", menuName = "Data/BattleSceneSetups/Events/EventActions/RewardEventAction", order = 0)]
public class RewardEventAction : EventAction
{
	[Header("Clearing Reward")]
	[SerializeField]
	protected ClearingReward clearingReward;

	[SerializeField]
	private bool raiseBackgroundPurpleForTransitionIgnoreParentGroups;

	[SerializeField]
	protected bool addDotAtTheEnd;

	protected MapHandler mapHandler => ReferenceSingleton<AssetsReference>.Instance.MapHandler;

	public override void ExecuteAction(EventButton eventButton)
	{
		if (raiseBackgroundPurpleForTransitionIgnoreParentGroups)
		{
			eventButton.ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value: true);
		}
		mapHandler.SetClearingReward(clearingReward);
	}

	public override string GetEventButtonResultText(string resultTextID)
	{
		string text = "";
		for (int i = 0; i < clearingReward.Rewards.Length; i++)
		{
			string text2 = clearingReward.Rewards[i].RewardName;
			if (addDotAtTheEnd)
			{
				text2 = string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), text2);
			}
			text += text2;
			if (i < clearingReward.Rewards.Length - 1)
			{
				text += "\n";
			}
		}
		return text;
	}
}
